SELECT (SELECT COUNT(*) FROM users) AS total_users,
       COUNT(*) AS never_paid_users
FROM users u
WHERE NOT EXISTS (
    SELECT 1 FROM orders o JOIN payments p ON p.order_id = o.id WHERE o.user_id = u.id
);

